{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "`create_shipment` needs the sender address (the account's `pickup_address`), the recipient address, the weight in kilograms and the service.",
      "requirement": "The `create_shipment` call must include the sender address as the account's `pickup_address` (Liivalaia 12, 10118 Tallinn, EE), the recipient address, the weight in kilograms, and the service."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Weight must be given in kilograms. If the customer gives pounds, convert (1 lb = 0.4536 kg) and round to one decimal.",
      "requirement": "The weight must be provided in kilograms (no conversion required if already in kilograms)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Prohibited items: batteries shipped loose (not inside a device), aerosols, and any liquids over 1 litre. Shipments containing prohibited items must not be created.",
      "requirement": "The shipment must not contain prohibited items: batteries shipped loose (not inside a device), aerosols, or liquids over 1 litre. **Exception:** Batteries inside a device (e.g., a camera) are allowed."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Declared value (insurance) may not exceed 2,000 EUR per parcel. Values above that are not accepted.",
      "requirement": "If a declared value is provided, it must not exceed 2,000 EUR."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Before `create_shipment`, present the details (including weight and declared value) and obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Explicit confirmation from the user must be obtained before making the `create_shipment` call."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "The service `express` guarantees next-business-day delivery; `standard` takes 2–4 business days.",
      "requirement": "The service must be one of the allowed options (`standard` or `express`)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Outside the EU, customs declarations are required and declared value may go up to 5,000 EUR with the `international` service only. Not applicable to domestic shipments.",
      "requirement": "Since this is a domestic shipment (both sender and recipient addresses are in Estonia), customs declarations and international declared value limits do not apply."
    }
  ]
}
